<script setup lang="ts">import{onMounted,ref}from'vue';import{Search}from'lucide-vue-next';import{api,when}from'../api';import{PageHeader}from'../components/Common.vue';const rows=ref<any[]>([]),filter=ref('');async function load(){rows.value=(await api<any>(`/audit?action=${encodeURIComponent(filter.value)}`)).items};onMounted(load);</script>
<template><PageHeader eyebrow="IMMUTABLE TRAIL" title="审计日志" description="追踪登录、配置、发布、运行控制、回滚与下载行为。"><div class="search"><Search/><input v-model="filter" placeholder="筛选操作类型" @keyup.enter="load"/></div></PageHeader><section class="table-card"><table><thead><tr><th>时间</th><th>操作人</th><th>操作</th><th>目标</th><th>结果</th><th>IP</th><th>摘要</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td>{{when(a.timestampUtc)}}</td><td><strong>{{a.userName}}</strong></td><td class="mono">{{a.action}}</td><td>{{a.target}}</td><td>{{a.result}}</td><td class="mono">{{a.ipAddress}}</td><td>{{a.details}}</td></tr></tbody></table></section></template>
